ignored.com%0d%0aGET%20http://{host}/%20HTTP/1.1%0d%0aHeader:%20value
ignored.com%0aHost:%20{host}
ignored.com%0dHost:%20{host}
ignored.com%20%0d%0aHost:%20{host}
